  },
  "devDependencies": {
    "@types/better-sqlite3": "^9.6.0",
    "@types/node": "^26.6.5",
    "mastra": "^1.33.0",
    "tsx": "^4.23.15",
    "typescript": "^6.0.3"
  }
}
import http from "node:http";
import { readFile } from "node:fs/promises";
import { toNodeHandler } from "better-auth/node";
import { auth } from "./auth";
import { requireUser } from "./auth/session";
import { bot } from "./bot/whatsapp";
import { handleChat, handleChatHistory, listAgents, sendJson } from "./chat-api";
import { createWebHandler } from "./web";

const policyPages: Record<string, URL> = {
  "/privacy": new URL("../public/privacy.html", import.meta.url),
  "/data-deletion": new URL("../public/data-deletion.html", import.meta.url),
};

const authHandler = toNodeHandler(auth);

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url ?? "/", `http://${req.headers.host ?? "localhost"}`);

  if (req.method === "GET" && url.pathname === "/health") {
    res.writeHead(200, { "content-type": "application/json" });
    res.end(JSON.stringify({ status: "ok" }));
    return;
  }

  if ((req.method === "GET" || req.method === "HEAD") && Object.hasOwn(policyPages, url.pathname)) {
    try {
      const page = await readFile(policyPages[url.pathname]);
      res.writeHead(200, { "content-type": "text/html; charset=utf-8" });
      res.end(req.method === "HEAD" ? undefined : page);
    } catch {
      res.writeHead(500).end("Page unavailable");
    }
    return;
  }

  // Meta webhook endpoint
  if (url.pathname === "/api/webhooks/whatsapp") {
    try {
      const chunks: Buffer[] = [];
      for await (const chunk of req) chunks.push(chunk);

      const webReq = new Request(url, {
        method: req.method,
        headers: req.headers as any,
        body: req.method === "POST" ? Buffer.concat(chunks) : undefined,
      });

      const response = await bot.webhooks.whatsapp(webReq);
      res.writeHead(response.status, Object.fromEntries(response.headers));
      res.end(await response.text());
    } catch (error: unknown) {
      console.error("WhatsApp webhook failed", error);
      if (!res.headersSent) res.writeHead(500);
      res.end("Webhook failed");
    }
    return;
  }

  // Better Auth endpoints (sign-in, sign-out, session)
  if (url.pathname === "/api/auth" || url.pathname.startsWith("/api/auth/")) {
    try {
      await authHandler(req, res);
    } catch (error: unknown) {
      console.error("Auth request failed", error);
      if (!res.headersSent) sendJson(res, 500, { error: "Auth failed" });
      else res.end();
    }
    return;
  }

  // Current user
  if (url.pathname === "/api/me") {
    if (req.method !== "GET") {
      res.writeHead(405, { allow: "GET" }).end();
      return;
    }
    const user = await requireUser(req, res);
    if (!user) return;
    sendJson(res, 200, { user });
    return;
  }

  // Web chat API
  if (url.pathname === "/api/agents") {
    if (req.method !== "GET") {
      res.writeHead(405, { allow: "GET" }).end();
      return;
    }
    const user = await requireUser(req, res);
    if (!user) return;
    sendJson(res, 200, listAgents(user));
    return;
  }

  const historyMatch = url.pathname.match(/^\/api\/chat\/([^/]+)\/history$/);
  if (historyMatch) {
    try {
      const user = await requireUser(req, res);
      if (!user) return;
      await handleChatHistory(decodeURIComponent(historyMatch[1]), req, res, user);
    } catch (error: unknown) {
      console.error("Chat history failed", error);
      if (!res.headersSent) sendJson(res, 500, { error: "Chat history failed" });
      else res.end();
    }
    return;
  }

  const chatMatch = url.pathname.match(/^\/api\/chat\/([^/]+)$/);
  if (chatMatch) {
    try {
      const user = await requireUser(req, res);
      if (!user) return;
      await handleChat(decodeURIComponent(chatMatch[1]), req, res, user);
    } catch (error: unknown) {
      console.error("Web chat failed", error);
      if (!res.headersSent) sendJson(res, 500, { error: "Chat failed" });
      else res.end();
    }
    return;
  }

  if (url.pathname === "/api" || url.pathname.startsWith("/api/")) {
    res.writeHead(404).end();
    return;
  }

  // Everything else is the web UI (Vite dev middleware, or web/dist in production).
  webHandler(req, res);
});

const webHandler = await createWebHandler(server);

const PORT = Number(process.env.PORT) || 3000;
server.listen(PORT, () => {
  console.log(`Server listening on port ${PORT}`);
});
import { createHash } from "node:crypto";
import { init, log, trace } from "neatlogs";

export const telemetryReady = init({
  workflowName: "nlhack",
  apiKey: process.env.NEATLOGS_API_KEY,
  captureLogs: true,
  debug: process.env.NEATLOGS_DEBUG === "true",
  ...(process.env.NEATLOGS_ENDPOINT ? { endpoint: process.env.NEATLOGS_ENDPOINT } : {}),
});

if (!process.env.NEATLOGS_API_KEY) {
  console.warn("NEATLOGS_API_KEY is missing: traces will not be exported to the dashboard.");
}

// Group WhatsApp turns without putting phone numbers in session identifiers.
export function conversationSessionId(threadId: string): string {
  return createHash("sha256").update(threadId).digest("hex");
}

export async function traceRequest<T>(
  channel: "whatsapp" | "cli",
  sessionId: string,
  run: () => Promise<T>,
  input?: unknown,
): Promise<T> {
  await telemetryReady;
  return trace({
    name: `${channel}.request`,
    kind: "WORKFLOW",
    sessionId,
    sessionEntryPoint: channel,
    input,
    attributes: { "app.channel": channel },
  }, async (activeSpan) => {
    console.info("Neatlogs trace started", { channel, traceId: activeSpan.spanContext().traceId, sessionId });
    log("Request started", { channel });
    try {
      const result = await run();
      log("Request completed", { channel });
      return result;
    } catch (error) {
      log("Request failed", { channel, level: "error", error: error instanceof Error ? error.message : String(error) });
      throw error;
    }
  });
}
